package org.railtracker.fois;
import android.app.*;import android.os.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.text.Html;import android.content.Intent;import java.net.*;import java.io.*;import java.util.regex.*;
public class MainActivity extends Activity {
 LinearLayout root; EditText query, captcha; TextView result; ImageView image; boolean dark=false; String last=""; final String base="https://www.fois.indianrail.gov.in/FOISWebPortal"; final String page=base+"/pages/FWP_FNREnq.jsp"; boolean ready=false;
 int bg(){return dark?0xff102039:0xffe8f1ff;} int fg(){return dark?0xffe9f2ff:0xff163453;}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(28);return d;}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg());t.setPadding(12,12,12,12);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(shape(0xff326bd4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);root.addView(b,p);b.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setTextColor(fg());e.setHintTextColor(0xff8295ad);e.setPadding(24,18,24,18);e.setBackground(shape(dark?0xff233957:0xfff8fbff));root.addView(e);return e;}
 public void onCreate(Bundle b){super.onCreate(b);CookieHandler.setDefault(new CookieManager(null,CookiePolicy.ACCEPT_ORIGINAL_SERVER));draw();}
 void draw(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,64,28,32);root.setBackgroundColor(bg());sc.addView(root);setContentView(sc);root.addView(label("FOIS  /  Rail Tracker",30));root.addView(label("Freight intelligence • Native enquiry",15));query=field("11-digit FNR or RMN CFS");query.setText(last);button("Search / Load verification",()->load());image=new ImageView(this);root.addView(image,new LinearLayout.LayoutParams(-1,130));captcha=field("Enter verification code");button("Get freight details",()->submit());button("Refresh verification",()->load());result=label("Enter a freight number to begin.",17);result.setTextIsSelectable(true);root.addView(result);button("Save result",()->{getPreferences(0).edit().putString("saved",result.getText().toString()).apply();});button("Saved result",()->result.setText(getPreferences(0).getString("saved","No saved result")));button("Share result",()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,result.getText().toString());startActivity(Intent.createChooser(i,"Share freight details"));});button("Light / Dark mode",()->{last=query.getText().toString();dark=!dark;ready=false;draw();});}
 byte[] request(String url,String data)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Referer",page);if(data!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(data.getBytes("UTF-8"));}}try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);return out.toByteArray();}finally{c.disconnect();}}
 void show(String s){runOnUiThread(()->result.setText(s));}
 void load(){last=query.getText().toString().trim();ready=false;if(!last.matches("[0-9]{11}")){show(last.matches("(?i)[a-z]{2,5} +[a-z]{2,5}")?"Station-pair enquiry requires an authorized ECBS session. Not implemented in this build.":"Enter a valid 11-digit FNR.");return;}show("Loading verification…");new Thread(()->{try{request(page,null);byte[] b=request(base+"/portalCaptcha.jpg?_="+System.currentTimeMillis(),null);Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length);if(bmp==null)throw new IOException("Verification image unavailable");runOnUiThread(()->{image.setImageBitmap(bmp);ready=true;result.setText("Enter the verification code and tap Get freight details.");});}catch(Exception e){show("Connection failed: "+e.getMessage());}}).start();}
 void submit(){String fnr=query.getText().toString().trim(),code=captcha.getText().toString().trim();if(!ready||!fnr.equals(last)||code.isEmpty()){show("Load verification for this FNR first.");return;}ready=false;show("Fetching freight details…");new Thread(()->{try{String enc=URLEncoder.encode(code,"UTF-8");String response=new String(request(base+"/FWP_FNREnq","Qry=FNR_ENQUIRY&txtFNRNumb="+fnr+"&captchaText="+enc),"UTF-8");Matcher m=Pattern.compile("(?is)ETA At Destination</b>\\s*</td>\\s*<td[^>]*>(.*?)</td>").matcher(response);if(m.find()){show("FNR  "+fnr+"\n\nExpected arrival\n"+Html.fromHtml(m.group(1),0).toString().trim());}else{show("No ETA returned. Check the FNR and refresh verification.");}}catch(Exception e){show("Enquiry failed: "+e.getMessage());}}).start();}
}